		return manifest, nil
	}
	if err := json.Unmarshal(data, &manifest); err != nil {
		// Treating a corrupt manifest as empty is the worst option available:
		// every file a previous export wrote becomes permanently unremovable,
		// nothing says so, and the directory quietly stops meaning what the
		// command says it means. Refusing is recoverable in one step, and the
		// error says which step.
		return manifest, fmt.Errorf("%s is unreadable (%w); delete it to start a fresh export, "+
			"which will leave any files a previous run wrote in place", factFilesManifestName, err)
	}
	return manifest, nil
}

// pruneStaleFactFiles removes files the last export wrote and this one did not.
//
// A fact that was retracted, or whose taxonomy path moved, leaves a file behind
// otherwise — and a grep over the export then returns something the brain no
// longer believes, presented exactly like something it does.
func pruneStaleFactFiles(dir string, previous factFilesManifest, written map[string]bool) {
	var dirs []string
	for _, rel := range previous.Files {
		if written[rel] {
			continue
		}
		// The manifest lives inside a directory the user can edit, so its
		// entries are input. Two different escapes have to be refused: a path
		// that climbs out textually, and a path whose components are all plain
		// names but whose parent is a symlink — the second is invisible to any
		// string check and is what redirects a delete outside --dir.
		//
		// The two checks overlap on the textual case (the symlink guard also
		// refuses ".."), so the test asserts the property rather than either
		// one: removing both lets a manifest entry delete outside --dir,
		// removing either alone does not.
		clean := filepath.Clean(rel)
		if filepath.IsAbs(clean) || clean == "." || strings.HasPrefix(clean, "..") {
			continue
		}
		if err := rejectExistingSymlinkPathComponents(dir, clean); err != nil {
			continue
		}
		if err := os.Remove(filepath.Join(dir, clean)); err != nil {
			continue
		}
		if parent := filepath.Dir(clean); parent != "." {
			dirs = append(dirs, parent)
		}
	}
	// Prune directories the removals emptied, deepest first, so a whole
	// taxonomy branch that no longer has facts does not linger as empty
	// folders. os.Remove refuses a non-empty directory, which is exactly the
	// guard wanted here.
	sort.Sort(sort.Reverse(sort.StringSlice(dirs)))
	for _, rel := range dirs {
		for current := rel; current != "."; current = filepath.Dir(current) {
			if err := rejectExistingSymlinkPathComponents(dir, current); err != nil {
				break
			}
			if err := os.Remove(filepath.Join(dir, current)); err != nil {
				break
			}
		}
	}
}

// writeFactFiles materialises facts under dir. Returns the relative paths
// written, sorted, so the caller can print or diff them deterministically.
//
// Files a previous export wrote and this one does not are removed, so the
// directory reflects the brain as it is now rather than the union of every
// export ever run.
func writeFactFiles(dir, branch string, facts []factRecord) (factFilesResult, error) {
	result := factFilesResult{Dir: dir}
	// The export root itself is checked below, AFTER MkdirAll rather than
	// before. Every path check in this function is relative to `dir`, so a
	// symlink AT dir is invisible to all of them — and this function both
	// writes and deletes. `export` applies the same rule to its output
	// directory; the wording is borrowed from it deliberately, because two
	// commands refusing the same thing for the same reason should say so the
	// same way.
	// Checked before MkdirAll as well as after, for the message rather than the
	// safety: MkdirAll's wording for "there is a file in the way" differs
	// between platforms, and this is a condition worth naming ourselves.
	if info, err := os.Lstat(dir); err == nil && !info.IsDir() && info.Mode()&os.ModeSymlink == 0 {
		return result, fmt.Errorf("output path exists and is not a directory: %s", dir)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return result, fmt.Errorf("create export directory: %w", err)
	}
	// Re-check after creating it. The check above is a time-of-check and this
	// is the time-of-use: between them, dir can be replaced by a symlink, and
	// every path check after this point is relative to dir and would follow it.
	// Checking the state we are actually about to write into is the only order
	// that means anything.
	info, err := os.Lstat(dir)
	if err != nil {
		return result, fmt.Errorf("stat export directory: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return result, fmt.Errorf("output directory must not be a symlink: %s", dir)
	}
	if !info.IsDir() {
		return result, fmt.Errorf("output path exists and is not a directory: %s", dir)
	}
	previous, err := readFactFilesManifest(dir)
	if err != nil {
		return result, err
	}
	// Two facts whose ids share a 12-character prefix inside one taxonomy
	// directory would land on the same filename. It takes an improbable
	// collision to happen at all, and the cost if it does is the part worth
	// guarding: the second write silently replaces the first while the result
	// still counts both, so a fact disappears from the projection and the
	// export reports success.
	claimed := make(map[string]string, len(facts))
	for _, fact := range facts {
		relDir := factFileDir(fact.Paths)
		// A symlink planted at any component of the taxonomy path redirects the
		// write out of --dir entirely. The `..` and absolute-path checks
		// elsewhere in this file do not catch that: every component is a plain
		// name and the escape happens in the filesystem, not in the string.
		// Every other place in this codebase that writes under a user-named
		// output directory checks this first.
		if err := rejectExistingSymlinkPathComponents(dir, relDir); err != nil {
			manifestErr := recordPartialExport(dir, branch, previous, result.Files)
			return result, withManifestFailure(fmt.Errorf("refusing to write into %s: %w", relDir, err), manifestErr)
		}
		absDir := filepath.Join(dir, relDir)
		if err := os.MkdirAll(absDir, 0o755); err != nil {
			manifestErr := recordPartialExport(dir, branch, previous, result.Files)
			return result, withManifestFailure(fmt.Errorf("create %s: %w", relDir, err), manifestErr)
		}
		rel := filepath.Join(relDir, factFileName(fact.ID))
		if owner, taken := claimed[rel]; taken {
			manifestErr := recordPartialExport(dir, branch, previous, result.Files)
			return result, withManifestFailure(fmt.Errorf("facts %s and %s both map to %s; one would silently replace the other", owner, fact.ID, rel), manifestErr)
		}
		claimed[rel] = fact.ID
		if err := rejectExistingSymlinkPathComponents(dir, rel); err != nil {
			manifestErr := recordPartialExport(dir, branch, previous, result.Files)
			return result, withManifestFailure(fmt.Errorf("refusing to write %s: %w", rel, err), manifestErr)
		}
		if err := os.WriteFile(filepath.Join(dir, rel), []byte(renderFactFile(fact)), 0o644); err != nil {
			manifestErr := recordPartialExport(dir, branch, previous, result.Files)
			return result, withManifestFailure(fmt.Errorf("write %s: %w", rel, err), manifestErr)
		}
		result.Files = append(result.Files, rel)
	}
	sort.Strings(result.Files)
	result.Written = len(result.Files)

	written := make(map[string]bool, len(result.Files))
	for _, rel := range result.Files {
		written[rel] = true
	}
	// Prune only what this branch's own previous export wrote. A manifest from
	// a different branch describes files that are not stale — they are another
	// branch's export, and deleting them is what made this destructive.
	if previous.Branch == branch {
		pruneStaleFactFiles(dir, previous, written)
	} else if len(previous.Files) > 0 {
		result.Warnings = append(result.Warnings, fmt.Sprintf(
			"%s was last exported for branch %q; its %d file(s) were left in place. "+
				"Use a separate --dir per branch to keep exports apart.",
			dir, previous.Branch, len(previous.Files)))
	}
	if err := writeFactFilesManifest(dir, branch, result.Files); err != nil {
		// The files are written; only the record of them failed. Returning it
		// matters because without the manifest the next export cannot
		// reconcile, and silence here would make that undiagnosable.
		return result, fmt.Errorf("export written, but recording it failed: %w", err)
	}
	return result, nil
}

// writeFactFilesManifest records what is on disk, so the next export can
// reconcile against a true record.
//
// Failure to write it is not returned: the export itself succeeded, and the
// cost of a missing manifest is that the next run prunes nothing, which is the
// safe direction.
func writeFactFilesManifest(dir, branch string, files []string) error {
	if err := rejectExistingSymlinkPathComponents(dir, factFilesManifestName); err != nil {
		// The manifest is a file like any other, in a directory somebody could
		// have planted a symlink in. Without this check it is the one write in
		// this function that could still be redirected out of --dir.
		return fmt.Errorf("refusing to write %s: %w", factFilesManifestName, err)
	}
	data, err := json.MarshalIndent(factFilesManifest{Branch: branch, Files: files}, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, factFilesManifestName), append(data, '\n'), 0o644)
}

// withManifestFailure keeps both halves of a failed export.
//
// When an export fails partway, the record of what it wrote can fail too — a
// full disk fails both. Discarding the second leaves the files orphaned with no
// manifest naming them and nothing saying so, which is the silent-orphan
// failure this file has now been bitten by twice.
func withManifestFailure(err, manifestErr error) error {
	if manifestErr == nil {
		return err
	}
	return fmt.Errorf("%w (and the partial export could not be recorded, so its files are not tracked: %w)", err, manifestErr)
}

// recordPartialExport keeps the manifest honest when an export fails partway.
//
// The previous version wrote the manifest only on success, with a comment
// claiming that a failed run left the old manifest describing what was on disk.
// That was wrong: the files written before the failure are on disk and in no
// manifest, so no later run would ever remove them. The manifest now covers the
// union — what a previous run left, plus what this one managed to write —
// which is exactly the set the next export needs to reconcile.
func recordPartialExport(dir, branch string, previous factFilesManifest, writtenSoFar []string) error {
	carried := writtenSoFar
	if previous.Branch == branch {
		// Only this branch's own previous files are ours to reconcile; another
		// branch's belong to its export.
		carried = append(append([]string{}, previous.Files...), writtenSoFar...)
	}
	seen := make(map[string]bool, len(carried))
	union := make([]string, 0, len(carried))
	for _, rel := range carried {
		if seen[rel] {
			continue
		}
		seen[rel] = true
		union = append(union, rel)
	}
	sort.Strings(union)
	return writeFactFilesManifest(dir, branch, union)
}

func newFactsFilesCommand(opts Options) *cobra.Command {
	var (
		dir        string
		branch     string
		jsonOut    bool
		includeAll bool
	)
	cmd := &cobra.Command{
		Use:   "files",
		Short: "Write durable facts out as plain Markdown files you can grep, read and diff",
		Long: "Write durable facts out as one Markdown file per fact, laid out by taxonomy path.\n\n" +
			"The export is a projection: the brain remains the source of truth, the directory is\n" +
			"rewritten on each run, and nothing reads these files back in. Edit them freely; edit\n" +
			"the brain with remember and retract.",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			_, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
			if err != nil {
				return err
			}
			facts, err := loadFacts(brainDir, resolvedBranch)
			if err != nil {
				return err
			}
			if !includeAll {
				// Retracted and superseded facts are history, not current
				// knowledge. Writing them beside live ones by default would
				// make a grep return things the brain no longer believes.
				active := facts[:0:0]
				for _, fact := range facts {
					if fact.Status == "" || fact.Status == "active" {
						active = append(active, fact)
					}
				}
				facts = active
			}
			result, err := writeFactFiles(dir, resolvedBranch, facts)
			if err != nil {
				return err
			}
			if jsonOut {
				return writeIndentedJSON(cmd.OutOrStdout(), result)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "wrote %d facts to %s\n", result.Written, result.Dir)
			for _, file := range result.Files {
				fmt.Fprintf(cmd.OutOrStdout(), "  %s\n", file)
			}
			// A directory holding two branches' exports is a thing the reader
			// has to know about — it is the difference between grepping this
			// branch's facts and grepping a mixture.
			for _, warning := range result.Warnings {
				fmt.Fprintf(cmd.ErrOrStderr(), "warning: %s\n", warning)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&dir, "dir", "brain-facts", "Directory to write the files into")
	cmd.Flags().StringVar(&branch, "branch", "", "Branch to export facts from (default: current)")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the manifest as JSON")
	cmd.Flags().BoolVar(&includeAll, "all", false, "Include superseded and retracted facts")
	return cmd
}

// memoriesToFacts converts normalised memories into fact records. now supplies
// the timestamp for any memory whose source carried none, so an undated import
// is dated at import time rather than at the zero value.
func memoriesToFacts(memories []importedMemory, skipped int, source, prefix, branch string, now time.Time) ([]factRecord, factImportReport) {
	// Read is what the file contained, not what survived parsing: "3 of 3"
	// when the file held four is exactly the silent drop this reports against.
	report := factImportReport{Source: source, Read: len(memories) + skipped, SkippedText: skipped}
	unsupported := map[string]bool{}
	facts := make([]factRecord, 0, len(memories))
	// Supersession is resolved after the loop, because a memory can be
	// replaced by one that appears later in the export and every fact needs
	// its id before any reference to it can be written.
	byForeignID := make(map[string]int, len(memories))
	duplicateForeignIDs := map[string]bool{}
	replaces := make([]string, 0, len(memories))
	for _, mem := range memories {
		paths := importedFactPaths(prefix, mem.Categories)
		created, updated := mem.CreatedAt, mem.UpdatedAt
		if created.IsZero() {
			created = now
		}
		if updated.IsZero() {
			updated = created
		}
		status := factStatusActive
		if mem.ReplacedBy != "" {
			// The source already superseded this memory. Importing it as
			// active would resurrect something its owner retired.
			status = factStatusSuperseded
			report.Superseded++
		}
		facts = append(facts, factRecord{
			ID:     factRecordID(mem.Text, paths),
			Paths:  paths,
			Text:   mem.Text,
			Branch: branch,
			Origin: factOriginImported,
			Status: status,
			// The anchor names where this came from. It is not evidence from
			// this repository and must not read like it: verify will report
			// these as unverifiable-here, correctly.
			Provenance: []factAnchor{{SessionID: source + ":" + mem.ForeignID}},
			CreatedAt:  created,
			UpdatedAt:  updated,
		})
		if mem.ForeignID != "" {
			if _, seen := byForeignID[mem.ForeignID]; seen {
				// A source id that appears twice cannot identify anything. Left
				// alone, the last occurrence wins and any replaced_by naming
				// that id resolves to whichever memory happened to be last in
				// the file — a supersession pointed at an arbitrary fact, which
				// is worse than no supersession because it looks deliberate.
				duplicateForeignIDs[mem.ForeignID] = true
			}
			byForeignID[mem.ForeignID] = len(facts) - 1
		}
		replaces = append(replaces, mem.ReplacedBy)
		for _, note := range mem.Unsupported {
			unsupported[note] = true
		}
	}
	// SupersededBy has to name a fact in THIS store. Writing the foreign id
	// would leave a reference that reconciliation and display look up and never
	// find — a dangling pointer dressed as lineage, which is worse than no
	// lineage because it reads as though it resolves. Where the replacement was
	// imported too, the reference is real; where it was not, the link cannot be
	// represented and is reported rather than invented.
	danglingSupersessions := 0
	ambiguousSupersessions := 0
	for i, foreignReplacement := range replaces {
		if foreignReplacement == "" {
			continue
		}
		if duplicateForeignIDs[foreignReplacement] {
			// Ambiguous: the id names more than one memory, so there is no
			// right answer and picking one would invent a relationship.
			ambiguousSupersessions++
			continue
		}
		target, ok := byForeignID[foreignReplacement]
		if !ok {
			danglingSupersessions++
			continue
		}
		facts[i].SupersededBy = facts[target].ID
	}
	if len(duplicateForeignIDs) > 0 {
		unsupported[fmt.Sprintf(
			"duplicate source ids (%d id(s) name more than one memory, so any supersession referring to them is ambiguous)",
			len(duplicateForeignIDs))] = true
	}
	if ambiguousSupersessions > 0 {
		unsupported[fmt.Sprintf(
			"supersession target is ambiguous (%d fact(s) name a duplicated source id and are left with no successor)",
			ambiguousSupersessions)] = true
	}
	if danglingSupersessions > 0 {
		unsupported[fmt.Sprintf(
			"supersession target outside this export (%d fact(s) are marked superseded with no successor in the store)",
			danglingSupersessions)] = true
	}

	// Two memories whose text and category normalise to the same thing are the
	// same fact under a content-addressed id, and upsert correctly folds them
	// into one. What was wrong was the count: report.Imported said two, so the
	// numbers disagreed with the store and nothing explained why.
	distinct := map[string]bool{}
	for _, fact := range facts {
		distinct[fact.ID] = true
	}
	if collapsed := len(facts) - len(distinct); collapsed > 0 {
		unsupported[fmt.Sprintf(
			"%d memor(ies) are identical to another under the same category and were merged into one fact",
			collapsed)] = true
	}
	for note := range unsupported {
		report.Unsupported = append(report.Unsupported, note)
	}
	sort.Strings(report.Unsupported)
	report.Imported = len(distinct)
	return facts, report
}

func newFactsImportCommand(opts Options) *cobra.Command {
	var (
		source  string
		file    string
		prefix  string
		branch  string
		dryRun  bool
		jsonOut bool
	)
	cmd := &cobra.Command{
		Use:   "import",
		Short: "Import durable facts from another memory tool's export",
		Long: "Import memories exported from another tool as durable facts.\n\n" +
			"Imported facts carry origin \"imported\" and an anchor naming the source tool and\n" +
			"the foreign id. They have no provenance in this repository, so `verify` reports\n" +
			"them as unverifiable-here — that is accurate, not a failure.\n\n" +
			"The mem0 mapping follows mem0's published API reference. Anything the source\n" +
			"expresses that Brain cannot represent is named in the report rather than dropped\n" +
			"silently.",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if strings.TrimSpace(file) == "" {
				return fmt.Errorf("--file is required")
			}
			data, err := readImportFile(file)
			if err != nil {
				return err
			}
			var memories []importedMemory
			var skipped int
			switch strings.ToLower(strings.TrimSpace(source)) {
			case "mem0":
				memories, skipped, err = parseMem0(data)
			default:
				return fmt.Errorf("unknown --source %q (supported: mem0)", source)
			}
			if err != nil {
				return err
			}
			if err := validateImportPrefix(prefix); err != nil {
				return err
			}
			_, brainDir, resolvedBranch, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), branch)
			if err != nil {
				return err
			}
			facts, report := memoriesToFacts(memories, skipped, strings.ToLower(source), prefix, resolvedBranch, opts.Now().UTC())
			report.File = file
			report.DryRun = dryRun

			keptActive := 0
			if !dryRun {
				if err := withBrainWriteLock(brainDir, func() error {
					existing, loadErr := loadFacts(brainDir, resolvedBranch)
					if loadErr != nil {
						return loadErr
					}
"}

