		return "", false, "egress is disabled by ENTIRE_BRAIN_NO_EGRESS/ENTIRE_BRAIN_LOCAL_ONLY"
	}
	raw := strings.TrimSpace(os.Getenv(webhookURLEnv))
	if raw == "" {
		return "", false, webhookURLEnv + " is not set"
